solution.javascript:
function pacificAtlantic(heights) {
  const m = heights.length, n = heights[0].length;
  const pac = new Set(), atl = new Set();
  function dfs(r, c, visited, prev) {
    if (r<0||r>=m||c<0||c>=n||visited.has(r+','+c)||heights[r][c]<prev) return;
    visited.add(r+','+c);
    const h = heights[r][c];
    dfs(r+1,c,visited,h); dfs(r-1,c,visited,h); dfs(r,c+1,visited,h); dfs(r,c-1,visited,h);
  }
  for (let c = 0; c < n; c++) { dfs(0, c, pac, -1); dfs(m-1, c, atl, -1); }
  for (let r = 0; r < m; r++) { dfs(r, 0, pac, -1); dfs(r, n-1, atl, -1); }
  const result = [];
  for (let r = 0; r < m; r++) for (let c = 0; c < n; c++) if (pac.has(r+','+c) && atl.has(r+','+c)) result.push([r,c]);
  return result;
}

solution.cpp:
vector<vector<int>> pacificAtlantic(vector<vector<int>>& heights) {
    int m = heights.size(), n = heights[0].size();
    vector<vector<bool>> pac(m, vector<bool>(n)), atl(m, vector<bool>(n));
    function<void(int,int,vector<vector<bool>>&,int)> dfs = [&](int r, int c, vector<vector<bool>>& v, int prev) {
        if (r<0||r>=m||c<0||c>=n||v[r][c]||heights[r][c]<prev) return;
        v[r][c] = true;
        int h = heights[r][c];
        dfs(r+1,c,v,h); dfs(r-1,c,v,h); dfs(r,c+1,v,h); dfs(r,c-1,v,h);
    };
    for (int c=0;c<n;c++) { dfs(0,c,pac,-1); dfs(m-1,c,atl,-1); }
    for (int r=0;r<m;r++) { dfs(r,0,pac,-1); dfs(r,n-1,atl,-1); }
    vector<vector<int>> result;
    for (int r=0;r<m;r++) for (int c=0;c<n;c++) if (pac[r][c]&&atl[r][c]) result.push_back({r,c});
    return result;
}
